# ----------------- RTCM MODULE -----------------
# RTCM message registry and stream manager (app/rtcm/): message metadata,
# group filtering, and cached routing of RTCM3 frames from base to rovers.
echo "Creating RTCM module..."

cat > $APP/notify.py << 'EOF'
"""Telegram notifications and remote control.

Two halves:

  * outbound - events from the caster are filtered against per-event settings
    and delivered to a chat;
  * inbound  - an optional long-polling loop accepts commands from a single
    administrator chat, so the system can be queried and muted from a phone.

Everything is failure-proof by construction: notification problems must never
affect the caster itself, so every path swallows its errors, sends run on
short-lived background threads, and the polling loop backs off on failure.
Uses urllib from the standard library rather than adding an HTTP dependency.
"""

import json
import logging
import os
import threading
import time
import urllib.error
import urllib.parse
import urllib.request

logger = logging.getLogger(__name__)

API_BASE = 'https://api.telegram.org/bot{token}/{method}'

# Events the operator can switch on and off individually. The key is the
# settings key; the label is what the UI shows.
EVENT_TYPES = (
    ('notify_station_up', 'Station connected'),
    ('notify_station_down', 'Station disconnected'),
    ('notify_station_error', 'Station error'),
    ('notify_rover_connect', 'Rover connected'),
    ('notify_rover_disconnect', 'Rover disconnected'),
    ('notify_backup', 'Backup result'),
    ('notify_service', 'Service start/stop'),
)

SETTING_KEYS = (
    'telegram_enabled',
    'telegram_bot_token',
    'telegram_chat_id',
    'telegram_admin_id',
    'telegram_commands_enabled',
    'telegram_language',
) + tuple(key for key, _ in EVENT_TYPES)

DEFAULT_EVENT_STATE = {
    'notify_station_up': True,
    'notify_station_down': True,
    'notify_station_error': True,
    'notify_rover_connect': False,
    'notify_rover_disconnect': False,
    'notify_backup': True,
    'notify_service': True,
}

DEFAULT_COOLDOWN_SECONDS = 60.0

_last_sent = {}
_pending_notifications = set()
_last_sent_lock = threading.Lock()
_poller_started = threading.Event()


def _is_true(value):
    return str(value).strip().lower() in ('1', 'true', 'yes', 'on')


def load_settings(app):
    """Read every notification setting. Returns a dict; never raises."""
    values = {}
    try:
        from app.db.models import SystemSetting, db

        with app.app_context():
            rows = SystemSetting.query.filter(
                SystemSetting.key.in_(SETTING_KEYS)
            ).all()
            values = {row.key: str(row.value or '') for row in rows}
            db.session.remove()
    except Exception as settings_error:
        logger.debug(f'Notification settings unavailable: {settings_error}')

    settings = {
        'enabled': _is_true(values.get('telegram_enabled', 'false')),
        'token': values.get('telegram_bot_token', '').strip(),
        'chat_id': values.get('telegram_chat_id', '').strip(),
        'admin_id': values.get('telegram_admin_id', '').strip(),
        'commands_enabled': _is_true(values.get('telegram_commands_enabled', 'false')),
        'language': 'ru' if values.get('telegram_language', '').strip().lower() == 'ru' else 'en',
        'events': {},
    }
    for key, _label in EVENT_TYPES:
        if key in values and values[key] != '':
            settings['events'][key] = _is_true(values[key])
        else:
            settings['events'][key] = DEFAULT_EVENT_STATE.get(key, True)
    return settings


def _set_setting(app, key, value):
    """Persist one setting. Used by chat commands."""
    from app.db.models import SystemSetting, db

    with app.app_context():
        row = SystemSetting.query.filter_by(key=key).first()
        if row is None:
            row = SystemSetting(key=key, value=str(value), description='')
            db.session.add(row)
        else:
            row.value = str(value)
        db.session.commit()
        db.session.remove()


def _call(token, method, params, timeout=15):
    payload = urllib.parse.urlencode(params).encode('utf-8')
    request = urllib.request.Request(
        API_BASE.format(token=token, method=method),
        data=payload,
        headers={'Content-Type': 'application/x-www-form-urlencoded'},
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read(65536)
    except urllib.error.HTTPError as http_error:
        # Telegram explains itself in the response body - "chat not found",
        # "Unauthorized", "bot was blocked by the user". Without reading it the
        # operator only sees "HTTP Error 400: Bad Request", which says nothing
        # about what to fix.
        try:
            body = http_error.read(65536)
        except Exception:
            return {'ok': False, 'description': f'HTTP {http_error.code}'}

    try:
        return json.loads(body.decode('utf-8', 'replace'))
    except ValueError:
        return {'ok': False, 'description': 'unparseable response'}


TELEGRAM_HINTS = {
    'chat not found': (
        'Telegram does not know this chat. Open a chat with your bot and send it '
        'any message first - bots cannot write to someone who never wrote to them.'
    ),
    'unauthorized': 'The bot token is wrong. Copy it again from @BotFather.',
    'bot was blocked': 'The bot is blocked in that chat. Unblock it and try again.',
    'chat_id is empty': 'No chat ID was set.',
}


def _explain(description):
    """Turn Telegram's terse reason into something actionable."""
    lowered = str(description or '').lower()
    for needle, hint in TELEGRAM_HINTS.items():
        if needle in lowered:
            return f'{description} - {hint}'
    return str(description or 'unknown error')


# Buttons for the common actions, so nothing has to be typed on a phone in the field.
MAIN_KEYBOARD = {
    'inline_keyboard': [
        [
            {'text': '\u2705 Ready?', 'callback_data': 'ready'},
            {'text': '\U0001f4ca Status', 'callback_data': 'status'},
        ],
        [
            {'text': '\U0001f4e1 Rovers', 'callback_data': 'rovers'},
            {'text': '\U0001f514 Alerts', 'callback_data': 'events'},
        ],
        [
            {'text': '\U0001f5a5 Server', 'callback_data': 'server'},
            {'text': '\U0001f4be Backup now', 'callback_data': 'backup'},
        ],
        [
            {'text': '\U0001f507 Mute', 'callback_data': 'mute'},
            {'text': '\U0001f514 Unmute', 'callback_data': 'unmute'},
        ],
        [
            {'text': '\u21bb Restart service', 'callback_data': 'restart'},
            {'text': '\U0001f501 Reboot', 'callback_data': 'reboot'},
        ],
        [
            {'text': '\u2753 Help', 'callback_data': 'help'},
        ],
    ]
}


def _post_message(token, chat_id, text, keyboard=None):
    params = {
        'chat_id': chat_id,
        'text': text,
        'disable_web_page_preview': 'true',
    }
    if keyboard:
        params['reply_markup'] = json.dumps(keyboard)

    parsed = _call(token, 'sendMessage', params)
    if parsed.get('ok'):
        return True, ''
    return False, _explain(parsed.get('description'))


def send(app, text, event=None, event_key=None, cooldown=DEFAULT_COOLDOWN_SECONDS):
    """Queue a notification. Returns immediately; never raises.

    `event` is one of EVENT_TYPES and decides whether this category is enabled;
    `event_key` de-duplicates repeats of the same specific occurrence.
    """
    if not app or not text:
        return

    if event_key:
        now_ts = time.monotonic()
        with _last_sent_lock:
            previous = _last_sent.get(event_key)
            if event_key in _pending_notifications or (previous is not None and now_ts - previous < cooldown):
                return
            _pending_notifications.add(event_key)

    def _worker():
        try:
            settings = load_settings(app)
            if not settings['enabled'] or not settings['token'] or not settings['chat_id']:
                return
            if event and not settings['events'].get(event, True):
                return
            ok, error_text = _post_message(settings['token'], settings['chat_id'], translate_bot(text, settings.get('language', 'en')))
            if ok and event_key:
                with _last_sent_lock:
                    _last_sent[event_key] = time.monotonic()
            elif not ok:
                logger.warning(f'Telegram notification rejected: {error_text}')
        except Exception as send_error:
            logger.warning(f'Telegram notification failed: {send_error}')
        finally:
            if event_key:
                with _last_sent_lock:
                    _pending_notifications.discard(event_key)

    try:
        threading.Thread(target=_worker, daemon=True, name='notify').start()
    except Exception:
        if event_key:
            with _last_sent_lock:
                _pending_notifications.discard(event_key)
        logger.warning('Telegram notification could not be queued')


def send_test(app, text='GNSS Caster: test notification'):
    """Synchronous send used by the "Send test message" button."""
    settings = load_settings(app)
    if not settings['token'] or not settings['chat_id']:
        return False, translate_bot('Bot token and chat ID are both required', settings.get('language', 'en'))
    if not settings['enabled']:
        return False, translate_bot('Notifications are disabled', settings.get('language', 'en'))
    try:
        return _post_message(settings['token'], settings['chat_id'], translate_bot(text, settings.get('language', 'en')))
    except Exception as send_error:
        return False, str(send_error)


# ---------------------------------------------------------------------------
# Inbound: commands from the administrator's chat
# ---------------------------------------------------------------------------

HELP_TEXT = (
    'Tap a button below, or type one of these:\n'
    '/ready - can I start surveying right now?\n'
    '/status - readiness plus stations and rovers\n'
    '/stations - per-station detail\n'
    '/rovers - connected rovers\n'
    '/server - host health: uptime, temperature, disk, memory\n'
    '/backup - make a backup now\n'
    '/restart - restart the caster service (asks first)\n'
    '/reboot - reboot the machine (asks first)\n'
    '/events - which notifications are on\n'
    '/on <event> - enable a notification\n'
    '/off <event> - disable a notification\n'
    '/mute - stop all notifications\n'
    '/unmute - resume notifications\n'
    '/help - this message\n\n'
    'Event names: ' + ', '.join(key.replace('notify_', '') for key, _ in EVENT_TYPES)
)


def _run_power_action(action):
    """Restart the service or reboot the host, via the privileged helper."""
    try:
        from app.bluetooth.core import _run_privileged_helper
    except Exception as import_error:
        return f'Cannot do that: {import_error}'

    command = 'reboot-host' if action == 'reboot' else 'restart-service'
    try:
        result = _run_privileged_helper([command], timeout=30)
    except Exception as run_error:
        return f'Could not run it: {run_error}'

    if result.returncode != 0:
        return f'Failed: {(result.stderr or "").strip()[:160]}'

    if action == 'reboot':
        return (
            '\U0001f501 Rebooting in a few seconds. The caster will be back in '
            'about a minute; you will get a "started" message when it is.'
        )
    return (
        '\U0001f501 Restarting the caster service. It should be back within '
        'about ten seconds.'
    )


CONFIRM_KEYBOARDS = {
    'reboot': {'inline_keyboard': [[
        {'text': '\u26a0\ufe0f Yes, reboot the host', 'callback_data': 'reboot_confirm'},
        {'text': 'Cancel', 'callback_data': 'help'},
    ]]},
    'restart': {'inline_keyboard': [[
        {'text': '\u21bb Yes, restart the service', 'callback_data': 'restart_confirm'},
        {'text': 'Cancel', 'callback_data': 'help'},
    ]]},
}


def _describe_server(app, language='en'):
    """Host health: the things that actually strand a field unit.

    Disk filling up, the card overheating, memory exhausted or a service that
    quietly died - none of which show up in the GNSS status but all of which
    end a survey.
    """
    lines = ['\U0001f5a5 Server']

    # Uptime
    try:
        with open('/proc/uptime', 'r') as handle:
            seconds = float(handle.read().split()[0])
        days, rest = divmod(int(seconds), 86400)
        hours, rest = divmod(rest, 3600)
        minutes = rest // 60
        uptime = f'{days}d {hours}h {minutes}m' if days else f'{hours}h {minutes}m'
        if language == 'ru':
            uptime = f'{days} д {hours} ч {minutes} мин' if days else f'{hours} ч {minutes} мин'
        lines.append(f'Uptime: {uptime}')
    except Exception:
        pass

    # Temperature - a Pi in a sealed box in the sun will throttle
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as handle:
            celsius = int(handle.read().strip()) / 1000.0
        warning = (' ⚠️ перегрев' if language == 'ru' else ' ⚠️ hot') if celsius >= 75 else ''
        lines.append(f'Temperature: {celsius:.0f}\u00b0C{warning}')
    except Exception:
        pass

    # Disk and memory
    try:
        import shutil

        usage = shutil.disk_usage('/')
        free_gb = usage.free / (1024 ** 3)
        used_pct = 100.0 * (usage.total - usage.free) / usage.total
        warning = (' ⚠️ мало места' if language == 'ru' else ' ⚠️ low') if free_gb < 1.0 else ''
        lines.append(f'Disk: {free_gb:.1f} GB free ({used_pct:.0f}% used){warning}')
    except Exception:
        pass

    try:
        meminfo = {}
        with open('/proc/meminfo', 'r') as handle:
            for line in handle:
                key, _, value = line.partition(':')
                meminfo[key.strip()] = value.strip()
        total_kb = int(meminfo.get('MemTotal', '0 kB').split()[0])
        available_kb = int(meminfo.get('MemAvailable', '0 kB').split()[0])
        if total_kb:
            lines.append(
                f'Memory: {available_kb / 1024:.0f} MB free of {total_kb / 1024:.0f} MB'
            )
    except Exception:
        pass

    # Load average
    try:
        load1, load5, _ = os.getloadavg()
        lines.append(f'Load: {load1:.2f} (5 min {load5:.2f})')
    except Exception:
        pass

    # Latest backup - a stale backup is worth knowing about
    try:
        backup_dir = '/opt/gnss-caster/backups'
        archives = [
            os.path.join(backup_dir, name)
            for name in os.listdir(backup_dir)
            if name.startswith('backup_')
        ]
        if archives:
            newest = max(archives, key=os.path.getmtime)
            age_hours = (time.time() - os.path.getmtime(newest)) / 3600.0
            age = f'{age_hours:.0f} h ago' if age_hours < 48 else f'{age_hours / 24:.0f} days ago'
            size_mb = os.path.getsize(newest) / (1024 ** 2)
            age = translate_bot(age, language)
            lines.append(f'Last backup: {age} ({size_mb:.1f} MB)')
        else:
            lines.append('Last backup: none yet')
    except Exception:
        pass

    return '\n'.join(lines)


def _start_backup(app):
    """Kick off a backup the same way the web interface does.

    Runs as a systemd transient unit through the privileged helper, so it
    survives this thread and behaves identically whether it was triggered from
    a browser or a chat. The archive lands in the chat by itself if uploads are
    enabled.
    """
    try:
        from app.bluetooth.core import _run_privileged_helper
    except Exception as import_error:
        return f'Cannot start a backup: {import_error}'

    unit_name = f'gnss-caster-backup-{int(time.time())}.service'
    try:
        result = _run_privileged_helper(
            ['systemd-job', 'backup', unit_name], timeout=30
        )
    except Exception as run_error:
        return f'Could not start the backup: {run_error}'

    if result.returncode != 0:
        return f'Backup could not be started: {(result.stderr or "").strip()[:160]}'

    return (
        'Backup started. It usually takes under a minute; the archive will '
        'arrive here if uploads are enabled.'
    )


def _describe_readiness(app, language='en'):
    """Readiness as a short message for a phone screen."""
    try:
        from app.bluetooth.core import bluetooth_manager

        report = bluetooth_manager.get_readiness()
    except Exception as readiness_error:
        return f'Readiness unavailable: {readiness_error}'

    if report.get('ready'):
        lines = ['\u2705 READY to survey']
    else:
        lines = ['\u26d4 NOT ready']

    for station in report.get('stations', []):
        mark = '\u2705' if station.get('ready') else '\u26d4'
        detail = []
        if station.get('satellites') is not None:
            detail.append(translate_bot(f"{station['satellites']} sats", language))
        if station.get('hdop') is not None:
            detail.append(f"HDOP {station['hdop']}")
        if station.get('fix'):
            detail.append(str(station['fix']))
        detail.append(translate_bot(f"{station.get('rovers', 0)} rover(s)", language))
        lines.append(f"{mark} {station.get('name')} - {', '.join(detail)}")
        for issue in station.get('issues', []):
            lines.append(f'    \u2022 {translate_bot(issue, language)}')

    for issue in report.get('issues', []):
        if not any(issue.startswith(f"{s.get('name')}:") for s in report.get('stations', [])):
            lines.append(f'\u2022 {issue}')

    return '\n'.join(lines)


def _describe_status(app, language='en'):
    try:
        from app.bluetooth.core import bluetooth_manager
        from app.rtcm.stream import stream_manager

        status = bluetooth_manager.get_status()
        connected = status.get('connected', 0)
        total = status.get('total_stations', 0)
        lines = [f'Stations: {connected}/{total} connected']
        for station in status.get('stations', []):
            state = 'connected' if station.get('connected') else (station.get('status') or 'disconnected')
            state = translate_bot(state, language)
            rate = (station.get('telemetry') or {}).get('data_rate_bps', 0) or 0
            lines.append(f"  - {station.get('name')}: {state}, {rate/1024:.1f} KB/s")
            if station.get('last_error') and not station.get('connected'):
                lines.append(f"    last error: {station['last_error'][:120]}")
        try:
            rover_total = sum(
                int((stats or {}).get('clients', 0) or 0)
                for stats in (stream_manager.get_stats() or {}).values()
            )
            lines.append(f'Rovers connected: {rover_total}')
        except Exception:
            pass
        return '\n'.join(lines)
    except Exception as status_error:
        return f'Status unavailable: {status_error}'


def _describe_rovers(app):
    try:
        from app.rtcm.stream import stream_manager

        stats = stream_manager.get_stats() or {}
        if not stats:
            return 'No active streams.'
        lines = []
        for base_id, entry in stats.items():
            clients = int((entry or {}).get('clients', 0) or 0)
            frames = int((entry or {}).get('frames_parsed', 0) or 0)
            lines.append(f'Base {base_id}: {clients} rover(s), {frames} frames decoded')
        return '\n'.join(lines)
    except Exception as rovers_error:
        return f'Rover information unavailable: {rovers_error}'


def _describe_events(settings):
    language = settings.get('language', 'en')
    lines = [translate_bot('Notifications:', language)]
    for key, label in EVENT_TYPES:
        state = 'on' if settings['events'].get(key, True) else 'off'
        lines.append(f"  {key.replace('notify_', ''):18s} {translate_bot(state, language)}  ({translate_bot(label, language)})")
    lines.append('')
    lines.append('Master switch: ' + translate_bot('on' if settings['enabled'] else 'off', language))
    return '\n'.join(lines)


def _handle_command_raw(app, settings, text):
    """Return the reply for a command, or None to stay silent."""
    parts = str(text or '').strip().split()
    if not parts:
        return None
    command = parts[0].lower().split('@')[0]
    argument = parts[1].lower() if len(parts) > 1 else ''

    if command in ('/start', '/help'):
        return HELP_TEXT
    if command == '/restart':
        return ('Restart the caster service? Rovers will lose corrections for '
                'a few seconds.', CONFIRM_KEYBOARDS['restart'])
    if command == '/restart_confirm':
        return _run_power_action('restart')
    if command == '/reboot':
        return ('Reboot the whole machine? Everything stops for about a minute. '
                'Try /restart first - it fixes most things.',
                CONFIRM_KEYBOARDS['reboot'])
    if command == '/reboot_confirm':
        return _run_power_action('reboot')
    if command in ('/server', '/host'):
        return _describe_server(app, settings.get('language', 'en'))
    if command == '/backup':
        return _start_backup(app)
    if command in ('/ready', '/readiness'):
        return _describe_readiness(app, settings.get('language', 'en'))
    if command == '/status':
        return _describe_readiness(app, settings.get('language', 'en')) + '\n\n' + _describe_status(app, settings.get('language', 'en'))
    if command == '/stations':
        return _describe_status(app, settings.get('language', 'en'))
    if command == '/rovers':
        return _describe_rovers(app)
    if command == '/events':
        return _describe_events(settings)
    if command == '/mute':
        _set_setting(app, 'telegram_enabled', 'false')
        return 'Notifications muted. Send /unmute to resume.'
    if command == '/unmute':
        _set_setting(app, 'telegram_enabled', 'true')
        return 'Notifications resumed.'
    if command in ('/on', '/off'):
        if not argument:
            return 'Usage: /on <event>\n\n' + _describe_events(settings)
        key = argument if argument.startswith('notify_') else f'notify_{argument}'
        if key not in dict(EVENT_TYPES):
            return f'Unknown event "{argument}".\n\n' + _describe_events(settings)
        _set_setting(app, key, 'true' if command == '/on' else 'false')
        return f"{key.replace('notify_', '')} is now {'on' if command == '/on' else 'off'}"
    return None


