        @app.route('/api/mountpoints/<int:id>/update', methods=['PUT'])
        @login_required
        def api_update_mountpoint(id):
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                mountpoint = MountPoint.query.get_or_404(id)
                data = request.json
                
                if 'name' in data:
                    # Same NTRIP-safe charset rule as in create (sourcetable safety).
                    mp_name = str(data['name'] or '').strip()
                    if not re.fullmatch(r'[A-Za-z0-9_-]{1,64}', mp_name):
                        return jsonify({'error': 'Mountpoint name must be 1-64 characters: letters, digits, "_" or "-"'}), 400
                    data['name'] = mp_name
                    # Check if name already exists (excluding current mountpoint)
                    existing = MountPoint.query.filter(MountPoint.name == data['name'], MountPoint.id != id).first()
                    if existing:
                        return jsonify({'error': 'Mountpoint with this name already exists'}), 400
                    mountpoint.name = data['name']
                
                if 'base_id' in data:
                    # Check if base station exists
                    base_station = BaseStation.query.get(data['base_id'])
                    if not base_station:
                        return jsonify({'error': 'Base station not found'}), 400
                    mountpoint.base_id = data['base_id']
                
                if 'description' in data:
                    mountpoint.description = data['description']
                
                if 'is_active' in data:
                    mountpoint.is_active = data['is_active']
                
                if 'rtcm_settings' in data:
                    mountpoint.rtcm_settings = json.dumps(data['rtcm_settings'])
                
                mountpoint.updated_at = int(time.time())
                db.session.commit()
                stream_manager.invalidate_filter_cache()
                return jsonify({'message': 'Mountpoint updated'}), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error updating mountpoint: {e}")
                return jsonify({'error': str(e)}), 500
        
