            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                mountpoint = MountPoint.query.get_or_404(id)
                
                # Check if any rovers are using this mountpoint
                rovers = Rover.query.all()
                for rover in rovers:
